"use strict";
const KEY="mva_alpha12", OLD={entries:"pvd_entries",devices:"pvd_devices",game:"pvd_game"};
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const localDb=get(KEY,{entries:get(OLD.entries,[]),devices:get(OLD.devices,[]),strains:[],photos:[],game:get(OLD.game,{xp:0,coins:0,quests:[],courses:{}})});
let db=localDb, storageMode="local", cloudSession=null, cloudKey=null, cloudSalt=null, cloudEnvelope=null, cloudTimer=null;
const put=()=>{if(storageMode==="local"){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){toast("Speicher fast voll. Exportiere ein Backup und verkleinere Fotos.")}}else scheduleCloudSave()};
for(const k of ["entries","devices","strains","photos"])if(!Array.isArray(db[k]))db[k]=[];
db.game ||= {xp:0,coins:0,quests:[],courses:{}}; db.game.quests ||= []; db.game.courses ||= {};
const defaults=[...["Venty","Mighty","Volcano","Dr. Dabber Switch2","TerpTorch","TerpHammer","Dynavap M7","Dynavap G3","Dynavap B2","The B","XMAX Qomo","Pax Flow","Cuboo Stick","Smono"].map(name=>({name,category:"vaporizer"})),...["GeekVape Legend 5","ELFX Mega"].map(name=>({name,category:"ecig"})),... ["IQOS","glo"].map(name=>({name,category:"heater"}))];
const names={vaporizer:"Vaporizer",ecig:"E-Zigarette",heater:"Tabakerhitzer"};
db.devices=db.devices.map(d=>typeof d==="string"?{name:d,category:"vaporizer"}:d);if(!db.devices.length)db.devices=defaults;else defaults.forEach(d=>{if(!db.devices.some(x=>x.name.toLowerCase()===d.name.toLowerCase()))db.devices.push(d)});
const $=s=>document.querySelector(s), esc=s=>String(s??"").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=()=>new Date().toISOString().slice(0,10), id=()=>crypto.randomUUID?.()||String(Date.now()+Math.random());
let page="home", pendingPhoto=null, csvPending=[], sortMode='desc', galleryIndex=0;
function toast(s){let t=document.createElement('div');t.className='toast';t.textContent=s;document.body.append(t);setTimeout(()=>t.remove(),2600)}
const cloudConfig=()=>window.MVA_CLOUD||{};
function cloudReady(){let c=cloudConfig();return /^https:\/\//.test(c.url||'')&&!!c.apiKey}
function b64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)))}
function unb64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function deriveCloudKey(password,salt){let material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:600000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function aesWrap(key,bytes){let iv=crypto.getRandomValues(new Uint8Array(12)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes);return {iv:b64(iv),ciphertext:b64(cipher)}}
async function aesUnwrap(key,box){return new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(box.iv)},key,unb64(box.ciphertext)))}
async function encryptCloud(data){if(!cloudKey)throw Error('Verschlüsselungsschlüssel fehlt');let iv=crypto.getRandomValues(new Uint8Array(12)),bytes=new TextEncoder().encode(JSON.stringify(data)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},cloudKey,bytes);return cloudEnvelope?{v:2,envelope:cloudEnvelope,iv:b64(iv),ciphertext:b64(cipher)}:{v:1,salt:b64(cloudSalt),iv:b64(iv),ciphertext:b64(cipher)}}
async function decryptCloud(box){if(box?.v===2&&box.envelope?.v===1){let env=box.envelope,salt=unb64(env.password.salt),kek=await deriveCloudKey(cloudPassword,salt),raw=await aesUnwrap(kek,env.password),rawKey=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt']);cloudKey=rawKey;cloudEnvelope=env;let plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(box.iv)},cloudKey,unb64(box.ciphertext));return JSON.parse(new TextDecoder().decode(plain))}if(box?.v!==1)throw Error('Unbekanntes Cloud-Backup-Format');cloudSalt=unb64(box.salt);cloudKey=await deriveCloudKey(cloudPassword,cloudSalt);cloudEnvelope=null;let plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(box.iv)},cloudKey,unb64(box.ciphertext));return JSON.parse(new TextDecoder().decode(plain))}
async function createCloudEnvelope(password){let raw=crypto.getRandomValues(new Uint8Array(32)),dek=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt']);let ps=crypto.getRandomValues(new Uint8Array(16)),pk=await deriveCloudKey(password,ps),pw=await aesWrap(pk,raw);let recovery=Array.from(crypto.getRandomValues(new Uint8Array(24)),x=>x.toString(16).padStart(2,'0')).join('');let rs=crypto.getRandomValues(new Uint8Array(16)),rk=await deriveCloudKey(recovery,rs),rw=await aesWrap(rk,raw);cloudKey=dek;cloudEnvelope={v:1,password:{salt:b64(ps),...pw},recovery:{salt:b64(rs),...rw}};return recovery}
let cloudPassword='';
async function cloudFetch(path,options={},retry=true){let c=cloudConfig(),res=await fetch(`${c.url.replace(/\/$/,'')}${path}`,{...options,headers:{apikey:c.apiKey,'Content-Type':'application/json',...(options.headers||{})}});if(res.status===401&&retry&&cloudSession?.refreshToken&&!path.startsWith('/auth/')){let rr=await fetch(`${c.url.replace(/\/$/,'')}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:c.apiKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:cloudSession.refreshToken})}),rd=await rr.json().catch(()=>({}));if(rr.ok){cloudSession.token=rd.access_token;cloudSession.refreshToken=rd.refresh_token;let headers={...(options.headers||{}),Authorization:`Bearer ${cloudSession.token}`};return cloudFetch(path,{...options,headers},false)}}let body=await res.text(),data=body?JSON.parse(body):null;if(!res.ok)throw Error(data?.msg||data?.message||data?.error_description||data?.hint||`Cloud-Fehler (${res.status})`);return data}
async function cloudAuth(email,password){if(!cloudReady())throw Error('Cloud ist noch nicht eingerichtet. Folge der Anleitung in cloud-setup.md.');let d=await cloudFetch('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})});return {token:d.access_token,refreshToken:d.refresh_token,userId:d.user.id,email:d.user.email}}
async function cloudSignup(email,password){if(!cloudReady())throw Error('Cloud ist noch nicht eingerichtet.');let d=await cloudFetch('/auth/v1/signup?redirect_to='+encodeURIComponent(location.origin+location.pathname),{method:'POST',body:JSON.stringify({email,password})});return d}
async function cloudResetEmail(email){let c=cloudConfig();let res=await fetch(`${c.url.replace(/\/$/,'')}/auth/v1/recover?redirect_to=${encodeURIComponent(location.origin+location.pathname)}`,{method:'POST',headers:{apikey:c.apiKey,'Content-Type':'application/json'},body:JSON.stringify({email})});let d=await res.json().catch(()=>({}));if(!res.ok)throw Error(d.msg||d.message||d.error_description||'E-Mail konnte nicht versendet werden')}
async function cloudRead(){let rows=await cloudFetch(`/rest/v1/mva_saves?select=payload&user_id=eq.${encodeURIComponent(cloudSession.userId)}&limit=1`,{headers:{Authorization:`Bearer ${cloudSession.token}`}});return rows?.[0]?.payload||null}
async function cloudWrite(){if(!cloudSession||!cloudKey)return;let payload=await encryptCloud(db);await cloudFetch('/rest/v1/mva_saves?on_conflict=user_id',{method:'POST',headers:{Authorization:`Bearer ${cloudSession.token}`,Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:cloudSession.userId,payload,updated_at:new Date().toISOString()})});setCloudStatus('Cloud gespeichert')}
function scheduleCloudSave(){if(!cloudSession||!cloudKey)return;setCloudStatus('Änderungen werden gespeichert …');clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>cloudWrite().catch(e=>{console.error(e);setCloudStatus('Cloud-Speicherung fehlgeschlagen');toast('Cloud-Speicherung fehlgeschlagen. Prüfe deine Verbindung und melde dich erneut an.') }),700)}
function setCloudStatus(text){let el=$('#storage-status');if(el)el.innerHTML=`<i></i> ${esc(text)}`}
function authEmail(){return $('#cloud-email')?.value.trim().toLowerCase()||''}
async function cloudLogin(signup){
 let email=authEmail(),password=$('#cloud-pass')?.value;
 if(!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))return toast('Bitte eine gültige E-Mail-Adresse eingeben.');
 if(!password||password.length<8)return toast('Das Kennwort muss mindestens 8 Zeichen haben.');
 let button=$('#cloud-connect');if(button){button.disabled=true;button.textContent='Einen Moment …'}
 try{
  if(signup){
   let d=await cloudSignup(email,password);
   if(!d.session){toast('Registrierung gestartet. Bitte bestätige zuerst den Link in deiner E-Mail.');return}
   cloudSession={token:d.session.access_token,refreshToken:d.session.refresh_token,userId:d.user.id,email:d.user.email};
  }else cloudSession=await cloudAuth(email,password);
  cloudPassword=password;
  let box=await cloudRead();
  if(box){
   let cloudData=await decryptCloud(box);
   openModal('Spielstand auswählen',`
    <p class="subheading">In deinem Cloud-Konto ist bereits ein Spielstand gespeichert. Entscheide, welche Daten künftig auf allen Geräten verwendet werden sollen.</p>
    <label class="card" style="display:block;margin:12px 0;cursor:pointer"><input type="radio" name="cloud-choice" value="local" style="width:auto;margin-right:8px"> <b>Lokalen Spielstand hochladen</b><div class="tagline" style="margin:7px 0 0">${localDb.entries.length} Einträge · ${localDb.devices.length} Geräte · ${localDb.strains.length} Sorten · ${localDb.photos.length} Fotos</div><p class="tagline">Ersetzt den bisherigen Cloud-Spielstand mit den Daten dieses Browsers.</p></label>
    <label class="card" style="display:block;margin:12px 0;cursor:pointer"><input type="radio" name="cloud-choice" value="cloud" checked style="width:auto;margin-right:8px"> <b>Cloud-Spielstand laden</b><div class="tagline" style="margin:7px 0 0">${cloudData.entries?.length||0} Einträge · ${cloudData.devices?.length||0} Geräte · ${cloudData.strains?.length||0} Sorten · ${cloudData.photos?.length||0} Fotos</div><p class="tagline">Ersetzt den aktuell angezeigten lokalen Spielstand auf diesem Gerät.</p></label>
    <p class="tagline">Dein JSON-Backup bleibt davon unberührt. Wähle bewusst aus, welcher Spielstand maßgeblich sein soll.</p>
   `,'Auswahl übernehmen',async()=>{
    let choice=$('[name="cloud-choice"]:checked')?.value;
    if(choice==='local'){
     if(!confirm('Wirklich den lokalen Spielstand hochladen und den bisherigen Cloud-Spielstand ersetzen?'))return;
     try{
      db=localDb;storageMode='cloud';await cloudWrite();
      setCloudStatus('Verschlüsselte Cloud · '+(cloudSession.email||''));
      $('#modal-root').innerHTML='';if($('#cloud-pass'))$('#cloud-pass').value='';render();toast('Lokaler Spielstand sicher in die Cloud übertragen');
     }catch(error){
      db=localDb;storageMode='local';setCloudStatus('Nur auf diesem Gerät');
      toast(error.message||'Upload fehlgeschlagen. Deine lokalen Daten bleiben erhalten.');
     }
    }else{
     db=cloudData;storageMode='cloud';setCloudStatus('Verschlüsselte Cloud · '+(cloudSession.email||''));
     $('#modal-root').innerHTML='';if($('#cloud-pass'))$('#cloud-pass').value='';render();toast('Cloud-Spielstand geladen');
    }
   });
  }else{
   if(!confirm('Dein Cloud-Konto ist noch leer. Soll der lokale Spielstand jetzt verschlüsselt hochgeladen werden?\\n\\n'+localDb.entries.length+' Einträge · '+localDb.devices.length+' Geräte · '+localDb.strains.length+' Sorten · '+localDb.photos.length+' Fotos')){
    cloudSession=null;cloudKey=null;cloudSalt=null;cloudEnvelope=null;cloudPassword='';storageMode='local';db=localDb;render();return;
   }
   db=localDb;storageMode='cloud';let recovery=await createCloudEnvelope(password);await cloudWrite();
   alert('Dein persönlicher Wiederherstellungscode lautet:\\n\\n'+recovery+'\\n\\nBewahre ihn sicher außerhalb dieses Geräts auf. Er wird nur einmal angezeigt und wird benötigt, um dein verschlüsseltes Tagebuch nach einem Passwort-Reset wieder zu öffnen.');
   if($('#cloud-pass'))$('#cloud-pass').value='';render();toast('Lokaler Spielstand sicher in die Cloud übertragen');
  }
 }catch(e){
  console.error(e);cloudSession=null;cloudKey=null;cloudSalt=null;cloudEnvelope=null;cloudPassword='';storageMode='local';db=localDb;setCloudStatus('Nur auf diesem Gerät');toast(e.message||'Cloud-Verbindung fehlgeschlagen');
 }finally{
  cloudPassword='';
  if(button){button.disabled=false;button.textContent='Anmelden'}
 }
}
async function sendPasswordReset(){let email=authEmail();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('Bitte zuerst deine E-Mail-Adresse eingeben.');try{await cloudResetEmail(email);toast('Wenn das Konto existiert, wurde eine E-Mail zum Zurücksetzen versendet.')}catch(e){toast(e.message||'Versand fehlgeschlagen')}}
async function changeCloudEmail(){
 if(!cloudSession||storageMode!=='cloud')return toast('Bitte zuerst anmelden.');
 const email=$('#cloud-change-email')?.value.trim().toLowerCase()||'';
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return toast('Bitte eine gültige E-Mail-Adresse eingeben.');
 if(email===String(cloudSession.email||'').toLowerCase())return toast('Diese E-Mail-Adresse ist bereits hinterlegt.');
 try{
  const redirectTo=location.origin+location.pathname;
  await cloudFetch('/auth/v1/user?redirect_to='+encodeURIComponent(redirectTo),{method:'PUT',headers:{Authorization:'Bearer '+cloudSession.token},body:JSON.stringify({email})});
  toast('Bestätigungslink wurde angefordert. Bitte prüfe dein E-Mail-Postfach und bestätige die neue Adresse.');
 }catch(error){toast(error.message||'E-Mail-Adresse konnte nicht geändert werden.')}
}
async function handlePasswordRecovery(){let hash=new URLSearchParams(location.hash.slice(1));if(hash.get('type')!=='recovery'||!hash.get('access_token'))return;let token=hash.get('access_token');history.replaceState(null,'',location.pathname+location.search);let recovery=prompt('Bitte gib deinen Vaping-Adventure-Wiederherstellungscode ein.');if(!recovery)return toast('Wiederherstellung abgebrochen.');let newPass=prompt('Bitte lege dein neues Passwort fest (mindestens 8 Zeichen).');if(!newPass||newPass.length<8)return toast('Passwort muss mindestens 8 Zeichen haben.');try{let c=cloudConfig(),headers={apikey:c.apiKey,'Content-Type':'application/json',Authorization:'Bearer '+token};let rr=await fetch(c.url.replace(/\/$/,'')+'/rest/v1/mva_saves?select=payload&limit=1',{headers});let rows=await rr.json();let box=rows?.[0]?.payload;if(!box||box.v!==2)throw Error('Für dieses Konto ist kein kompatibler Wiederherstellungsschlüssel vorhanden.');let env=box.envelope,rs=unb64(env.recovery.salt),rk=await deriveCloudKey(recovery,rs),raw=await aesUnwrap(rk,env.recovery),dek=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt']);let ps=crypto.getRandomValues(new Uint8Array(16)),pk=await deriveCloudKey(newPass,ps),pw=await aesWrap(pk,raw);env.password={salt:b64(ps),...pw};let up=await fetch(c.url.replace(/\/$/,'')+'/auth/v1/user',{method:'PUT',headers,body:JSON.stringify({password:newPass})});if(!up.ok)throw Error('Neues Passwort konnte nicht gespeichert werden.');box.envelope=env;let ur=await fetch(c.url.replace(/\/$/,'')+'/auth/v1/user',{headers});let ud=await ur.json();if(!ur.ok||!ud.id)throw Error('Konto konnte nicht bestätigt werden.');let wr=await fetch(c.url.replace(/\/$/,'')+'/rest/v1/mva_saves?on_conflict=user_id',{method:'POST',headers:{...headers,Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:ud.id,payload:box,updated_at:new Date().toISOString()})});if(!wr.ok)throw Error('Verschlüsselungsschlüssel konnte nicht aktualisiert werden. Bitte den Support kontaktieren.');toast('Passwort geändert. Bitte melde dich jetzt mit dem neuen Passwort an.')}catch(e){console.error(e);toast(e.message||'Wiederherstellung fehlgeschlagen. Prüfe den Code.')}}
function emptyDb(){return {entries:[],devices:defaults.map(x=>({...x})),strains:[],photos:[],game:{xp:0,coins:0,quests:[],courses:{}}}}
function switchLocal(){if(storageMode==='local')return;clearTimeout(cloudTimer);storageMode='local';db=localDb;cloudSession=null;cloudKey=null;cloudSalt=null;cloudPassword='';setCloudStatus('Nur auf diesem Gerät');render();toast('Lokaler Spielstand aktiviert')}
function emptyDb(){return {entries:[],devices:defaults.map(x=>({...x})),strains:[],photos:[],game:{xp:0,coins:0,quests:[],courses:{}}}}
function switchLocal(){if(storageMode==='local')return;clearTimeout(cloudTimer);storageMode='local';db=localDb;cloudSession=null;cloudKey=null;cloudSalt=null;cloudPassword='';setCloudStatus('Nur auf diesem Gerät');render();toast('Lokaler Spielstand aktiviert')}
function updateNav(){document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.querySelector('#diary-count').textContent=db.entries.length;setCloudStatus(storageMode==='cloud'?`Verschlüsselte Cloud · ${cloudSession?.email||''}`:'Nur auf diesem Gerät');updateProfile()}
function updateProfile(){
 const trigger=$('#profile-trigger'),menu=$('#profile-menu'),initial=$('#profile-initial');
 if(!trigger||!menu||!initial)return;
 const active=!!cloudSession&&storageMode==='cloud';
 const name=active?(cloudSession.username||'Dein Profil'):'Gastmodus';
 const email=active?(cloudSession.email||''):'';
 initial.textContent=active?String(name).trim().charAt(0).toUpperCase()||'P':'G';
 trigger.setAttribute('aria-label',active?'Profil von '+name+' öffnen':'Profilmenü öffnen');
 menu.innerHTML=active
  ? `<h3 class="profile-title">Dein Profil</h3><div class="profile-name">${esc(name)}</div><div class="profile-email">${esc(email)}</div><div class="profile-state"><i></i> Verschlüsselte Cloud aktiv</div><div class="profile-actions"><button class="btn soft" data-profile-action="backup">Speicher & Backup öffnen →</button><button class="btn" data-profile-action="logout">Abmelden</button></div>`
  : `<h3 class="profile-title">Dein Profil</h3><div class="profile-name">Gastmodus</div><div class="profile-email">Du bist aktuell nicht mit einem Cloud-Konto angemeldet.</div><div class="profile-state"><i></i> Nur auf diesem Gerät gespeichert</div><div class="profile-actions"><button class="btn primary" data-profile-action="backup">Cloud-Konto verbinden →</button></div>`;
}
async function logoutProfile(){
 if(storageMode==='cloud'){await switchLocal();if(storageMode==='cloud')return}
 cloudSession=null;cloudKey=null;cloudSalt=null;cloudPassword='';
 const menu=$('#profile-menu'),trigger=$('#profile-trigger');if(menu)menu.hidden=true;if(trigger)trigger.setAttribute('aria-expanded','false');
 updateNav();toast('Du wurdest abgemeldet.');
}
function go(p){page=p;updateNav();render();window.scrollTo(0,0)}

document.addEventListener('click',e=>{
 const trigger=e.target.closest('#profile-trigger');
 const menu=$('#profile-menu');
 if(trigger&&menu){
  const opening=menu.hidden;
  updateProfile();
  menu.hidden=!opening;
  trigger.setAttribute('aria-expanded',String(opening));
  return;
 }
 const action=e.target.closest('[data-profile-action]');
 if(action){
  if(menu)menu.hidden=true;
  $('#profile-trigger')?.setAttribute('aria-expanded','false');
  if(action.dataset.profileAction==='backup')go('backup');
  if(action.dataset.profileAction==='logout')logoutProfile();
  return;
 }
 if(menu&&!menu.hidden&&!e.target.closest('#profile-menu')){
  menu.hidden=true;
  $('#profile-trigger')?.setAttribute('aria-expanded','false');
 }
});

document.addEventListener('click',e=>{let n=e.target.closest('[data-page]');if(n){e.preventDefault();go(n.dataset.page)}});
const header=(eyebrow,title,sub,action='')=>`<div class="row mobile-stack"><div><div class="eyebrow">${eyebrow}</div><h1 class="heading">${title}</h1><p class="subheading">${sub}</p></div>${action}</div>`;
const card=(label,value,note)=>`<div class="card"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-caption">${note}</div></div>`;
const empty=(title,desc,button)=>`<div class="card empty">✳<b>${title}</b>${desc}<div style="margin-top:12px">${button||''}</div></div>`;
function render(){updateNav();let v=$('#view');v.className='main';({home:home,diary:diary,strains:strains,devices:devices,gallery:gallery,quests:quests,learn:learn,backup:backup,more:more}[page]||home)(v)}
function more(v){v.innerHTML=`${header('WEITERE BEREICHE','Mehr entdecken','Hier findest du deine Geräte, Fotosammlung, Lerninhalte und Einstellungen.','')}<div class="grid cards2 more-grid"><button class="card more-link" data-page="devices"><span class="more-icon">▱</span><b>Geräte</b><small>Deine Geräte verwalten und Fotos ergänzen</small><span class="more-arrow">Öffnen →</span></button><button class="card more-link" data-page="gallery"><span class="more-icon">▧</span><b>Photo Gallery</b><small>Deine Bilder und besonderen Momente</small><span class="more-arrow">Öffnen →</span></button><button class="card more-link" data-page="learn"><span class="more-icon">◉</span><b>Education</b><small>Kurse, Wissen und Sicherheit</small><span class="more-arrow">Öffnen →</span></button><button class="card more-link" data-page="backup"><span class="more-icon">⇧</span><b>Speicher & Backup</b><small>Cloud, Sicherung und Datenimport</small><span class="more-arrow">Öffnen →</span></button></div>`;bindGlobal()}
function home(v){let last=[...db.entries].sort((a,b)=>(b.date||'').localeCompare(a.date||'' )).slice(0,3),xp=Number(db.game.xp)||0,level=Math.floor(xp/100)+1;v.innerHTML=`${header('DEIN PERSÖNLICHES TAGEBUCH','Schön, dass du da bist.','Halte deine Sessions, Geräte und Entdeckungen an einem Ort fest.','<button class="btn primary" data-action="new">＋ Neuer Eintrag</button>')}<div class="hero"><div><div class="eyebrow">DEIN ADVENTURE BEGINNT HIER</div><h2>Dein Weg. Deine Aufzeichnungen.</h2><p>Dokumentiere deine Erfahrungen, lerne deine Geräte kennen und sammle Fortschritt durch Wissen und gute Pflege.</p><button class="btn" data-page="diary">Zum Tagebuch →</button></div><div class="hero-stat"><strong>Level ${level}</strong><small>${xp} XP gesammelt · ${db.game.coins||0} Coins</small></div></div><div class="grid stats">${card('TAGEBUCHEINTRÄGE',db.entries.length,'Deine dokumentierten Sessions')}${card('GERÄTE',db.devices.length,'In deiner Sammlung')}${card('PUFFS / ZÜGE',db.entries.reduce((a,x)=>a+(Number(x.puffs)||0),0).toLocaleString('de-DE'),'Optional erfasste Gesamtzahl')}${card('SORTEN',db.strains.length,'In deiner Sammlung')}</div><div class="grid split"><section><div class="row section-head"><h3>Zuletzt im Tagebuch</h3><a data-page="diary">Alle ansehen →</a></div>${last.length?`<div class="list">${last.map(entryRow).join('')}</div>`:empty('Deine Geschichte beginnt hier','Dein erster Eintrag wartet auf dich.','<button class="btn soft" data-action="new">Eintrag erstellen</button>')}</section><section><div class="row section-head"><h3>Dein nächster Schritt</h3><a data-page="quests">Alle Quests →</a></div><div class="card"><span class="pill">WISSEN & PFLEGE</span><h3 style="font:700 15px Manrope;margin:12px 0 7px">Lerne etwas Neues</h3><p class="subheading">Kurse zu Akkusicherheit, Reinigung und Gerätekunde.</p><button class="btn soft" style="margin-top:16px" data-page="learn">Kurse entdecken →</button></div></section></div>`;bindGlobal()}
function entryRow(x){return `<div class="item"><div class="item-icon">${x.category==='heater'?'♨':x.category==='ecig'?'◉':'✳'}</div><div class="item-content"><b>${esc(x.device||'Session')}</b><small>${esc(x.date||'')} · ${esc(x.strain||x.material||'Keine Sorte angegeben')} ${x.puffs?'· '+esc(x.puffs)+' Züge':''}</small></div><span class="pill">${esc(names[x.category]||x.category||'Session')}</span></div>`}
function diary(v){let items=[...db.entries].filter(x=>{let q=($('#search')?.value||'').toLowerCase();return(!q||Object.values(x).join(' ').toLowerCase().includes(q))&&(!$('#df')?.value||x.device===$('#df').value)&&(!$('#dc')?.value||x.category===$('#dc').value)}).sort((a,b)=>(sortMode==='desc'?-1:1)*(a.date||'').localeCompare(b.date||''));v.innerHTML=`${header('DEINE AUFZEICHNUNGEN','Vaping Diary',storageMode==='cloud'?'Deine Sessions und Eindrücke im verschlüsselten Cloud-Spielstand.':'Deine Sessions und Eindrücke, lokal auf diesem Gerät gespeichert.','<button class="btn primary" data-action="new">＋ Neuer Eintrag</button>')}<div class="toolbar"><input class="field" type="search" id="search" placeholder="Suche in Einträgen …" value="${esc($('#search')?.value||'')}"><select class="field" id="df"><option value="">Alle Geräte</option>${db.devices.map(d=>`<option ${$('#df')?.value===d.name?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select class="field" id="dc"><option value="">Alle Kategorien</option>${Object.entries(names).map(([k,n])=>`<option value="${k}" ${$('#dc')?.value===k?'selected':''}>${n}</option>`).join('')}</select><select class="field" id="sort"><option value="desc" ${sortMode==='desc'?'selected':''}>Neueste zuerst</option><option value="asc" ${sortMode==='asc'?'selected':''}>Älteste zuerst</option></select></div><div class="list">${items.length?items.map(x=>`<div class="card"><div class="row"><div><b>${esc(x.device||'Session')}</b><div class="tagline">${esc(x.date||'')} · ${esc(x.time||'')} · ${esc(names[x.category]||x.category||'')}</div></div><div class="inline-actions"><button class="btn small" data-edit="${esc(x.id)}">Bearbeiten</button><button class="btn small" data-delete-entry="${esc(x.id)}">Löschen</button></div></div><div class="tagline">${[x.strain,x.puffs&&`${x.puffs} Züge`,x.duration&&`${x.duration} min`,x.location,x.temp&&`${x.temp}°C`].filter(Boolean).map(esc).join(' · ')}</div>${x.notes?`<p class="subheading" style="margin-top:10px">${esc(x.notes)}</p>`:''}</div>`).join(''):empty('Keine Einträge gefunden','Passe deine Suche an oder dokumentiere eine neue Session.')}</div>`;
['search','df','dc','sort'].forEach(k=>$('#'+k)?.addEventListener(k==='search'?'input':'change',()=>{if(k==='sort')sortMode=$('#sort').value;let pos=$('#search')?.value;diary(v);if(pos){$('#search').focus();$('#search').setSelectionRange(pos.length,pos.length)}}));bindGlobal()}
function openModal(title,content,saveLabel='Speichern',fn){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="row"><h2>${title}</h2><button class="btn small" data-close>Schließen</button></div>${content}<div class="modal-foot"><button class="btn" data-close>Abbrechen</button><button class="btn primary" id="modal-save">${saveLabel}</button></div></div></div>`;$('#modal-root').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal-root').innerHTML='');$('#modal-root').querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''};$('#modal-save').onclick=fn}
function selectDevice(cat,selected=''){let opts=db.devices.filter(x=>!cat||x.category===cat);return `<option value="">Gerät auswählen (optional)</option>${opts.map(d=>`<option value="${esc(d.name)}" ${d.name===selected?'selected':''}>${esc(d.name)}</option>`).join('')}`}
function entryForm(e={}){let editing=!!e.id;openModal(editing?'Eintrag bearbeiten':'Neue Session',`<div class="formgrid"><div class="formrow"><label>Datum</label><input class="field" id="f-date" type="date" value="${esc(e.date||now())}"></div><div class="formrow"><label>Uhrzeit</label><input class="field" id="f-time" type="time" value="${esc(e.time||new Date().toTimeString().slice(0,5))}"></div><div class="formrow"><label>Geräteklasse</label><select class="field" id="f-cat">${Object.entries(names).map(([k,n])=>`<option value="${k}" ${e.category===k?'selected':''}>${n}</option>`)}</select></div><div class="formrow"><label>Gerät</label><select class="field" id="f-device">${selectDevice(e.category||'vaporizer',e.device||'')}</select></div><div class="formrow"><label>Sorte / Material</label><input class="field" id="f-strain" list="strains-list" value="${esc(e.strain||'')}" placeholder="Aus Sammlung wählen oder neu eingeben"><datalist id="strains-list">${db.strains.map(s=>`<option>${esc(s.name)}</option>`).join('')}</datalist></div><div class="formrow"><label>Puffs / Züge · optional</label><input class="field" id="f-puffs" type="number" min="0" value="${esc(e.puffs||'')}" placeholder="Optional"></div><div class="formrow"><label>Dauer · Minuten</label><input class="field" id="f-duration" type="number" min="0" value="${esc(e.duration||'')}"></div><div class="formrow"><label>Temperatur · °C</label><input class="field" id="f-temp" type="number" value="${esc(e.temp||'')}"></div><div class="formrow"><label>Ort</label><input class="field" id="f-location" value="${esc(e.location||'')}"></div><div class="formrow"><label>Geschmack · 1–5</label><select class="field" id="f-taste"><option value="">Keine Angabe</option>${[1,2,3,4,5].map(n=>`<option ${String(e.taste)===String(n)?'selected':''}>${n}</option>`)}</select></div><div class="formrow full"><label>Notizen</label><textarea class="field" id="f-notes">${esc(e.notes||'')}</textarea></div><div class="formrow full"><label><input type="checkbox" id="f-save-strain" style="width:auto" checked> Neue Sorte automatisch in meiner Sammlung speichern</label></div></div>`,editing?'Änderungen speichern':'Eintrag speichern',()=>{let x={...(e||{}),id:e.id||id(),date:$('#f-date').value,time:$('#f-time').value,category:$('#f-cat').value,device:$('#f-device').value,strain:$('#f-strain').value.trim(),puffs:$('#f-puffs').value,duration:$('#f-duration').value,temp:$('#f-temp').value,location:$('#f-location').value,taste:$('#f-taste').value,notes:$('#f-notes').value.trim()};let puffMatch=x.notes.match(/(?:anzahl\s*)?(?:züge|zuege|puffs?)\s*[:=]?\s*(\d+)/i);if(!x.puffs&&puffMatch)x.puffs=puffMatch[1];if($('#f-save-strain').checked&&x.strain&&!db.strains.some(s=>s.name.toLowerCase()===x.strain.toLowerCase()))db.strains.push({id:id(),name:x.strain,category:'',notes:''});if(e.id)db.entries=db.entries.map(a=>a.id===e.id?x:a);else{db.entries.unshift(x);db.game.xp+=3}put();$('#modal-root').innerHTML='';render();toast('Eintrag gespeichert')});$('#f-cat').onchange=()=>$('#f-device').innerHTML=selectDevice($('#f-cat').value)}
function strains(v){v.innerHTML=`${header('DEINE SAMMLUNG','My Strain Collection','Speichere Sortennamen und Notizen für deine Tagebucheinträge.','<button class="btn primary" data-action="new-strain">＋ Sorte hinzufügen</button>')}<div class="toolbar"><input class="field" id="strain-search" placeholder="Sorten durchsuchen …"></div><div class="grid cards2" id="strain-list">${strainCards()}</div>`;$('#strain-search').oninput=()=>$('#strain-list').innerHTML=strainCards($('#strain-search').value);bindGlobal()}
function strainCards(q=''){let a=db.strains.filter(s=>!q||JSON.stringify(s).toLowerCase().includes(q.toLowerCase()));return a.length?a.map(s=>`<div class="card"><div class="row"><div><span class="pill">${esc(s.category||'SAMMLUNG')}</span><h3 style="font:700 16px Manrope;margin:12px 0 3px">${esc(s.name)}</h3><div class="tagline">${esc(s.manufacturer||'Hersteller nicht angegeben')}</div></div><div class="inline-actions"><button class="btn small" data-edit-strain="${s.id}">Bearbeiten</button><button class="btn small" data-del-strain="${s.id}">Löschen</button></div></div>${s.notes?`<p class="subheading">${esc(s.notes)}</p>`:''}</div>`).join(''):empty('Noch keine Sorten','Füge deine erste Sorte hinzu.')}
function strainForm(s={}){openModal(s.id?'Sorte bearbeiten':'Sorte hinzufügen',`<div class="formgrid"><div class="formrow"><label>Sortenname</label><input class="field" id="s-name" value="${esc(s.name||'')}"></div><div class="formrow"><label>Hersteller</label><input class="field" id="s-maker" value="${esc(s.manufacturer||'')}"></div><div class="formrow"><label>Kategorie</label><input class="field" id="s-cat" placeholder="z. B. Blüte, Liquid" value="${esc(s.category||'')}"></div><div class="formrow full"><label>Notizen</label><textarea class="field" id="s-notes">${esc(s.notes||'')}</textarea></div></div>`, 'Sorte speichern',()=>{let x={id:s.id||id(),name:$('#s-name').value.trim(),manufacturer:$('#s-maker').value.trim(),category:$('#s-cat').value.trim(),notes:$('#s-notes').value.trim()};if(!x.name)return toast('Bitte einen Sortennamen eintragen');if(s.id)db.strains=db.strains.map(a=>a.id===s.id?x:a);else db.strains.push(x);put();$('#modal-root').innerHTML='';render()})}
function devices(v){v.innerHTML=`${header('DEINE AUSRÜSTUNG','Geräte','Verwalte deine Geräteklassen, Beschreibungen und Fotos.','<button class="btn primary" data-action="new-device">＋ Gerät hinzufügen</button>')}<div class="grid cards2">${db.devices.length?db.devices.map(d=>`<div class="card"><div class="photo">${d.photo?`<img src="${d.photo}">`:'▱'}</div><div class="row" style="margin-top:13px"><div><span class="pill">${names[d.category]||'Gerät'}</span><h3 style="font:700 15px Manrope;margin:8px 0 4px">${esc(d.name)}</h3></div><div class="inline-actions"><button class="btn small" data-edit-device="${esc(d.name)}">Bearbeiten</button><button class="btn small" data-del-device="${esc(d.name)}">Löschen</button></div></div><p class="subheading">${esc(d.description||'Noch keine Beschreibung')}</p></div>`).join(''):empty('Noch keine Geräte','Füge dein erstes Gerät hinzu.')}</div>`;bindGlobal()}
function deviceForm(d={}){pendingPhoto=null;openModal(d.name?'Gerät bearbeiten':'Gerät hinzufügen',`<div class="formgrid"><div class="formrow"><label>Gerätename</label><input class="field" id="d-name" value="${esc(d.name||'')}"></div><div class="formrow"><label>Geräteklasse</label><select class="field" id="d-cat">${Object.entries(names).map(([k,n])=>`<option value="${k}" ${d.category===k?'selected':''}>${n}</option>`)}</select></div><div class="formrow full"><label>Beschreibung</label><textarea class="field" id="d-desc">${esc(d.description||'')}</textarea></div><div class="formrow full"><label>Gerätefoto · wird mit dem Spielstand gespeichert</label><input class="field" type="file" id="d-photo" accept="image/*"><small class="muted">Ein neues Foto ersetzt das bisherige.</small>${d.photo?`<div class="photo"><img src="${d.photo}"></div>`:''}</div></div>`, 'Gerät speichern',()=>{let name=$('#d-name').value.trim();if(!name)return toast('Bitte Namen eintragen');let saveD=photo=>{let x={name,category:$('#d-cat').value,description:$('#d-desc').value.trim(),photo:photo||d.photo||''};if(d.name)db.devices=db.devices.map(a=>a.name===d.name?x:a);else db.devices.push(x);put();$('#modal-root').innerHTML='';render()};let f=$('#d-photo').files[0];if(f)compress(f,saveD);else saveD(null)})}
function compress(file,done){let r=new FileReader();r.onload=()=>{let im=new Image();im.onload=()=>{let c=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(im.width,im.height));c.width=im.width*scale;c.height=im.height*scale;c.getContext('2d').drawImage(im,0,0,c.width,c.height);done(c.toDataURL('image/jpeg',.76))};im.src=r.result};r.readAsDataURL(file)}
function gallery(v){v.innerHTML=`${header('DEINE MOMENTE','My Photo Gallery','Fotos werden mit dem aktiven Spielstand gespeichert und können Sessions oder Geräten zugeordnet werden.','<button class="btn primary" data-action="new-photo">＋ Foto hinzufügen</button>')}<div class="grid gallery-grid">${db.photos.length?db.photos.map((p,i)=>`<article class="card gallery-card"><button class="gallery-thumb" type="button" data-gallery-open="${i}" aria-label="Foto ${i+1} groß anzeigen"><img src="${p.src}" alt="${esc(p.title||'Galeriefoto')}"></button><div class="row gallery-meta"><div class="gallery-caption"><b>${esc(p.title||'Moment')}</b><div class="tagline">${esc(p.date||'')} · ${esc(p.device||p.entry||'Allgemein')}</div></div><button class="btn small" data-del-photo="${p.id}" aria-label="Foto löschen">Löschen</button></div></article>`).join(''):empty('Deine Galerie ist noch leer','Füge Fotos von Geräten oder besonderen Momenten hinzu.')}</div>`;bindGlobal()}
function showGalleryLightbox(){if(!db.photos.length)return;galleryIndex=(galleryIndex+db.photos.length)%db.photos.length;const p=db.photos[galleryIndex];$('#modal-root').innerHTML=`<div class="gallery-lightbox" role="dialog" aria-modal="true" aria-label="Foto-Großansicht"><div class="gallery-lightbox-panel"><div class="gallery-lightbox-top"><span>${esc(p.title||'Moment')}</span><button type="button" class="gallery-lightbox-close" data-lightbox-close aria-label="Großansicht schließen">×</button></div><div class="gallery-lightbox-stage"><button type="button" class="gallery-lightbox-nav" data-lightbox-prev aria-label="Vorheriges Bild">‹</button><img src="${p.src}" alt="${esc(p.title||'Galeriefoto')}"><button type="button" class="gallery-lightbox-nav" data-lightbox-next aria-label="Nächstes Bild">›</button></div><div class="gallery-lightbox-bottom"><span>${esc(p.date||'')} · ${esc(p.device||p.entry||'Allgemein')}</span><span>${galleryIndex+1} / ${db.photos.length}</span></div></div></div>`;document.body.style.overflow='hidden'}
function closeGalleryLightbox(){const root=$('#modal-root');if(root?.querySelector('.gallery-lightbox')){root.innerHTML='';document.body.style.overflow=''}}
document.addEventListener('click',e=>{const open=e.target.closest('[data-gallery-open]');if(open){galleryIndex=Number(open.dataset.galleryOpen)||0;showGalleryLightbox();return}if(e.target.closest('[data-lightbox-close]')||e.target.classList.contains('gallery-lightbox')){closeGalleryLightbox();return}if(e.target.closest('[data-lightbox-prev]')){galleryIndex--;showGalleryLightbox();return}if(e.target.closest('[data-lightbox-next]')){galleryIndex++;showGalleryLightbox()}});
document.addEventListener('keydown',e=>{if(!$('#modal-root .gallery-lightbox'))return;if(e.key==='Escape'){closeGalleryLightbox();e.preventDefault()}else if(e.key==='ArrowLeft'){galleryIndex--;showGalleryLightbox();e.preventDefault()}else if(e.key==='ArrowRight'){galleryIndex++;showGalleryLightbox();e.preventDefault()}});
function photoForm(){openModal('Foto hinzufügen',`<div class="formgrid"><div class="formrow full"><label>Foto</label><input class="field" type="file" id="p-file" accept="image/*" required></div><div class="formrow"><label>Bezeichnung</label><input class="field" id="p-title" placeholder="Mein Gerät …"></div><div class="formrow"><label>Datum</label><input class="field" id="p-date" type="date" value="${now()}"></div><div class="formrow full"><label>Zu Gerät</label><select class="field" id="p-device"><option value="">Keine Zuordnung</option>${db.devices.map(d=>`<option>${esc(d.name)}</option>`).join('')}</select></div><div class="formrow full"><label>Zu Tagebucheintrag</label><select class="field" id="p-entry"><option value="">Keine Zuordnung</option>${db.entries.map(e=>`<option value="${e.id}">${esc(e.date)} · ${esc(e.device||'Session')}</option>`).join('')}</select></div></div>`,'Foto speichern',()=>{let f=$('#p-file').files[0];if(!f)return toast('Bitte ein Foto auswählen');compress(f,src=>{db.photos.push({id:id(),src,title:$('#p-title').value,date:$('#p-date').value,device:$('#p-device').value,entry:$('#p-entry').value});put();$('#modal-root').innerHTML='';render()})})}
const questData=[{id:'diary1',name:'Erster Eintrag',desc:'Dokumentiere deinen ersten Tagebucheintrag.',xp:10,coins:5,check:()=>db.entries.length>=1},{id:'device',name:'Ausrüstung im Blick',desc:'Füge ein Gerät mit Beschreibung hinzu.',xp:15,coins:8,check:()=>db.devices.some(d=>d.description)},{id:'gallery',name:'Augenblicke festhalten',desc:'Ergänze ein Foto in deiner Galerie.',xp:15,coins:8,check:()=>db.photos.length>=1},{id:'learn',name:'Wissen wächst',desc:'Bestehe einen Lernkurs.',xp:25,coins:12,check:()=>Object.values(db.game.courses).some(c=>c.passed)}];
function quests(v){let xp=db.game.xp||0,lvl=Math.floor(xp/100)+1,week=db.entries.filter(e=>{let d=new Date(e.date),n=new Date();return d>=new Date(n-7*864e5)}).length;v.innerHTML=`${header('FORTSCHRITT OHNE KONSUMZIELE','Quests & Adventure','Belohnungen gibt es für Dokumentation, Lernen und Gerätepflege.','')}<div class="grid stats">${card('LEVEL',lvl,`${xp%100}/100 XP bis zum nächsten Level`)}${card('XP',xp,'Durch Wissen und Pflege')}${card('COINS',db.game.coins||0,'Deine Lernbelohnungen')}${card('WOCHENZIEL',`${Math.min(week,3)} / 3`,'Dokumentationstagebuch · freiwillig')}</div><div class="progress"><i style="width:${xp%100}%"></i></div><div class="section-head"><h3>Deine Quests</h3></div><div class="grid cards2">${questData.map(q=>{let done=db.game.quests.includes(q.id),ready=q.check();return `<div class="card"><span class="pill">${done?'ABGESCHLOSSEN':'QUEST'}</span><h3 style="font:700 16px Manrope">${q.name}</h3><p class="subheading">${q.desc}</p><div class="tagline">+${q.xp} XP · +${q.coins} Coins</div><button class="btn ${ready&&!done?'primary':'soft'} small" style="margin-top:14px" data-claim="${q.id}" ${done||!ready?'disabled':''}>${done?'Erledigt ✓':ready?'Belohnung abholen':'Noch nicht erreicht'}</button></div>`}).join('')}</div>`;bindGlobal()}
const courses=[{id:'battery',title:'Akkusicherheit',level:'Grundlagen',xp:30,coins:25,lessons:['Beschädigte Akkus nicht weiterverwenden.','Lose Lithium-Ionen-Akkus gegen Kurzschluss schützen.','Nur passende Ladegeräte nach Herstellerangaben nutzen.','Akkus trocken und geschützt lagern.'],questions:[['Was machst du mit einem beschädigten Akku?',['Weiterverwenden','Nicht weiterverwenden','Mit Klebeband reparieren'],1],['Wie transportierst du lose Akkus?',['Ungeschützt','Mit Schlüsseln zusammen','In einer geeigneten Schutzhülle'],2],['Welches Ladegerät nutzt du?',['Geeignet nach Herstellerangaben','Irgendein Netzteil','Beschädigtes Kabel'],0]]},{id:'clean',title:'Reinigung & Pflege',level:'Grundlagen',xp:20,coins:15,lessons:['Gerät vor der Reinigung ausschalten und abkühlen lassen.','Anweisungen des Herstellers beachten.','Keine Flüssigkeit in Elektronik oder Akkuöffnungen bringen.'],questions:[['Wann reinigst du ein Gerät?',['Eingeschaltet','Ausgeschaltet und abgekühlt','Während des Ladens'],1],['Was vermeidest du?',['Herstellerhinweise','Flüssigkeit in Elektronik','Abkühlen lassen'],1]]},{id:'device-basics',title:'Gerätekunde',level:'Einführung',xp:20,coins:15,lessons:['Lies Bedienungsanleitung und Warnhinweise.','Prüfe Gerät und Zubehör regelmäßig.','Nutze nur kompatible Teile.'],questions:[['Wo findest du passende Nutzungshinweise?',['Bedienungsanleitung','Beliebige Werbung','Nirgends'],0]]}];
function learn(v){let done=Object.values(db.game.courses).filter(c=>c.passed).length;v.innerHTML=`${header('LERNEN & WISSEN','Education','Kurse zu Bedienung, Sicherheit, Pflege und gesundheitlicher Aufklärung.','')}<div class="card" style="margin:20px 0"><div class="row"><div><span class="eyebrow">DEIN LERNFORTSCHRITT</span><h3 style="font:700 16px Manrope;margin:8px 0">${done} von ${courses.length} Kursen bestanden</h3></div><span class="pill">${db.game.coins||0} COINS</span></div><div class="progress"><i style="width:${done/courses.length*100}%"></i></div></div><div class="grid cards2">${courses.map(c=>{let r=db.game.courses[c.id];return `<article class="card course"><span class="pill">${c.level.toUpperCase()} · ${c.lessons.length} LEKTIONEN</span><h3 style="font:700 17px Manrope;margin:13px 0 6px">${c.title}</h3><p class="subheading">Lerne wichtige Grundlagen und beantworte anschließend einen kurzen Wissenstest.</p><div class="tagline" style="margin:12px 0">${r?.passed?'Bestanden · '+r.score+'%':`Belohnung: ${c.xp} XP · ${c.coins} Coins`}</div><button class="btn soft" data-course="${c.id}">${r?.passed?'Ergebnis ansehen':'Kurs öffnen'} →</button></article>`}).join('')}</div><p class="tagline" style="margin-top:20px">Lerninhalte sind allgemeine Informationen und ersetzen keine Herstellerhinweise oder medizinische Beratung.</p>`;bindGlobal()}
function courseView(c){let old=db.game.courses[c.id];openModal(c.title,`<div><span class="pill">${c.level}</span><h3>Kurzübersicht</h3><ul>${c.lessons.map(x=>`<li class="subheading" style="margin:9px 0">${esc(x)}</li>`).join('')}</ul><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h3>Wissenstest</h3>${c.questions.map((q,i)=>`<div class="formrow" style="margin:14px 0"><label>${i+1}. ${esc(q[0])}</label>${q[1].map((a,j)=>`<label style="font-weight:400"><input type="radio" name="cq${i}" value="${j}" style="width:auto"> ${esc(a)}</label>`).join('')}</div>`).join('')}</div>`,old?.passed?'Ergebnis speichern':'Prüfung abgeben',()=>{let score=0;for(let i=0;i<c.questions.length;i++){let a=$(`[name="cq${i}"]:checked`);if(!a)return toast('Bitte alle Fragen beantworten');if(+a.value===c.questions[i][2])score++}let pct=Math.round(score/c.questions.length*100),passed=pct>=80,was=old?.passed;if(passed&&!was){db.game.xp+=c.xp;db.game.coins+=c.coins}db.game.courses[c.id]={passed:passed||was,score:pct,date:now(),...(old?.passed?{coins:old.coins}:passed?{coins:c.coins}:{})};put();$('#modal-root').innerHTML='';render();toast(`${passed?'Bestanden':'Noch nicht bestanden'} · ${pct}%`)})}
function backup(v){let cloudCard=storageMode==='cloud'?`<div class="card"><span class="pill">AKTIV · VERSCHLÜSSELT</span><h3 style="font:700 16px Manrope">Cloud-Konto: ${esc(cloudSession?.username||'')}</h3><p class="subheading">Spielstände werden vor dem Senden mit AES-GCM verschlüsselt. Dein Kennwort wird nur für die Anmeldung verwendet und bleibt im Arbeitsspeicher dieser Sitzung.</p><div class="formrow" style="margin:14px 0"><label for="cloud-change-email">E-Mail-Adresse hinterlegen / ändern</label><input class="field" id="cloud-change-email" type="email" autocomplete="email" maxlength="254" value="${esc(cloudSession?.email||'')}" placeholder="name@beispiel.de"></div><button class="btn soft" data-action="cloud-change-email">Bestätigungslink anfordern</button><p class="tagline">Deine Konto-ID und dein verschlüsselter Cloud-Spielstand bleiben erhalten.</p><button class="btn" data-action="switch-local">Zu lokalem Spielstand wechseln</button></div>`:`<div class="card"><span class="pill">OPTIONAL · AES-GCM</span><h3 style="font:700 16px Manrope">Verschlüsselte Cloud</h3><p class="subheading">Mit E-Mail-Adresse und Kennwort anmelden. Der Cloud-Spielstand ist vom lokalen Spielstand getrennt. Beim ersten Verbinden kannst du vorhandene lokale Daten verschlüsselt hochladen.</p>${cloudReady()?'':`<p class="tagline" style="color:#9b5c27">Einmalige Einrichtung erforderlich: Supabase-Projekt konfigurieren. Siehe cloud-setup.md.</p>`}<div class="formrow" style="margin:13px 0 8px"><label for="cloud-email">E-Mail-Adresse</label><input class="field" id="cloud-email" type="email" autocomplete="email" maxlength="254" placeholder="name@beispiel.de" ${cloudReady()?'':'disabled'}></div><div class="formrow" style="margin:8px 0 12px"><label for="cloud-pass">Kennwort · mindestens 8 Zeichen</label><input class="field" id="cloud-pass" type="password" autocomplete="current-password" minlength="8" ${cloudReady()?'':'disabled'}></div><button class="btn primary" id="cloud-connect" data-action="cloud-login" ${cloudReady()?'':'disabled'}>Anmelden</button> <button class="btn soft" data-action="cloud-signup" ${cloudReady()?'':'disabled'}>Registrieren</button> <button class="text-btn" data-action="cloud-reset" ${cloudReady()?'':'disabled'}>Passwort vergessen?</button><p class="tagline">Du erhältst eine E-Mail zur Bestätigung. Jeder Account hat ausschließlich Zugriff auf seinen eigenen Cloud-Spielstand.</p></div>`;v.innerHTML=`${header('DEINE DATEN, DEINE KONTROLLE','Datensicherung','Wechsle zwischen lokalem Spielstand und verschlüsselter Cloud. Exportiere zusätzlich ein Backup.','')}<div class="grid cards2" style="margin-top:23px">${cloudCard}<div class="card"><span class="pill">EMPFOHLEN</span><h3 style="font:700 16px Manrope">JSON-Backup</h3><p class="subheading">Enthält Tagebuch, Geräte, Sortensammlung, Fotos, Quests und Lernfortschritt. Fotos können die Datei groß machen.</p><button class="btn primary" data-action="export-json">Backup herunterladen</button></div><div class="card"><span class="pill">WIEDERHERSTELLEN</span><h3 style="font:700 16px Manrope">Backup einspielen</h3><p class="subheading">Ein Backup ersetzt den aktiven Spielstand. Vorher wird eine Sicherheitskopie heruntergeladen.</p><input type="file" id="json-file" class="field" accept=".json,application/json"><button class="btn soft" data-action="import-json" style="margin-top:10px">JSON auswählen & einspielen</button></div><div class="card"><span class="pill">TAGEBUCH</span><h3 style="font:700 16px Manrope">CSV</h3><p class="subheading">Exportiere deine Tagebucheinträge oder importiere eine CSV mit Vorschau und Duplikaterkennung.</p><button class="btn" data-action="export-csv">CSV exportieren</button><label class="btn soft" style="display:inline-block;margin:8px 0">CSV importieren<input id="csv-file" hidden type="file" accept=".csv,text/csv"></label><div id="csv-preview"></div></div><div class="card"><span class="pill">${storageMode==='cloud'?'VERSCHLÜSSELTE CLOUD':'LOKALE SPEICHERUNG'}</span><h3 style="font:700 16px Manrope">Aktiver Spielstand</h3><p class="subheading">${storageMode==='cloud'?'Cloudspeicherung ist aktiv. Deine lokalen Daten bleiben auf diesem Gerät erhalten.':'Die Daten liegen nur in diesem Browser, bis du sie in ein verbundenes Cloud-Konto überträgst.'}</p><div class="tagline">${db.entries.length} Einträge · ${db.devices.length} Geräte · ${db.strains.length} Sorten · ${db.photos.length} Fotos</div></div></div>`;bindGlobal();$('#csv-file').onchange=importCsv;$('#json-file').onchange=importJson}
function csvExport(){let cols=['date','time','category','device','duration','puffs','strain','temp','location','taste','notes'],labels=['Datum','Uhrzeit','Kategorie','Gerät','Dauer','Puffs','Sorte','Temperatur','Ort','Geschmack','Notizen'],csv=[labels,...db.entries.map(e=>cols.map(k=>e[k]||''))].map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(';')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'my-vaping-diary.csv')}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function jsonExport(){download(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'my-vaping-adventure-backup.json')}
function importJson(e){let f=e.target.files[0];if(!f)return;let r=new FileReader;r.onload=()=>{try{let x=JSON.parse(r.result);if(!x||!Array.isArray(x.entries)||!Array.isArray(x.devices))throw 0;if(!confirm('Dieses Backup ersetzt alle aktuellen lokalen Daten. Fortfahren?'))return;jsonExport();Object.assign(db,x);put();render();toast('Backup wiederhergestellt')}catch{toast('Die Datei ist kein gültiges Backup')}};r.readAsText(f)}
function parseCsv(t){let delim=(t.split(/\r?\n/)[0].match(/;/g)||[]).length>=(t.split(/\r?\n/)[0].match(/,/g)||[]).length?';':',',rows=[],r=[],s='',q=false;t=t.replace(/^\uFEFF/,'');for(let i=0;i<t.length;i++){let c=t[i];if(c==='"'&&q&&t[i+1]==='"'){s+='"';i++}else if(c==='"')q=!q;else if(c===delim&&!q){r.push(s);s=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&t[i+1]==='\n')i++;r.push(s);s='';if(r.some(x=>x.trim()))rows.push(r);r=[]}else s+=c}r.push(s);if(r.some(x=>x.trim()))rows.push(r);return rows}
function importCsv(e){let f=e.target.files[0];if(!f)return;f.text().then(t=>{let rows=parseCsv(t),h=rows.shift().map(x=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z]/g,''));csvPending=rows.map(r=>{let o={};h.forEach((k,i)=>o[k]=r[i]||'');let pick=(...keys)=>keys.map(k=>o[k]).find(Boolean)||'';let notes=pick('notizen','notes','bemerkungen'),puffs=pick('puffs','zuege','anzahlzuege')||((notes.match(/(?:züge|zuege|puffs?)\s*[:=]?\s*(\d+)/i)||[])[1]||'');return {id:id(),date:pick('datum','date'),time:pick('uhrzeit','zeit','time'),category:pick('kategorie','category')||'vaporizer',device:pick('geraet','device'),strain:pick('sorte','strain','material'),duration:pick('dauer','duration'),puffs,notes,temp:pick('temperatur','temp'),location:pick('ort','location'),taste:pick('geschmack','taste')}}).filter(x=>x.device||x.date||x.notes);let dup=x=>db.entries.some(y=>x.date===y.date&&x.time===y.time&&x.device.toLowerCase()===String(y.device).toLowerCase());$('#csv-preview').innerHTML=`<p class="subheading">${csvPending.length} erkannt · ${csvPending.filter(x=>!dup(x)).length} neu · ${csvPending.filter(dup).length} mögliche Duplikate. ${csvPending.slice(0,10).map(x=>`<br>${esc(x.date)} · ${esc(x.device)} ${dup(x)?'· Duplikat':''}`).join('')}</p><button class="btn primary" id="csv-commit" ${csvPending.filter(x=>!dup(x)).length?'':'disabled'}>Neue Einträge übernehmen</button>`;$('#csv-commit').onclick=()=>{csvPending.filter(x=>!dup(x)).forEach(x=>{db.entries.push(x);if(!db.devices.some(d=>d.name.toLowerCase()===x.device.toLowerCase()))db.devices.push({name:x.device,category:x.category})});put();render();toast('CSV importiert')}}).catch(()=>toast('CSV konnte nicht gelesen werden'))}
function bindGlobal(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'new':entryForm();break;case'new-strain':strainForm();break;case'new-device':deviceForm();break;case'new-photo':photoForm();break;case'export-json':jsonExport();break;case'export-csv':csvExport();break;case'import-json':$('#json-file').click();break;case'cloud-login':cloudLogin(false);break;case'cloud-signup':cloudLogin(true);break;case'cloud-reset':sendPasswordReset();break;case'cloud-change-email':changeCloudEmail();break;case'switch-local':switchLocal();break}});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>entryForm(db.entries.find(x=>x.id===b.dataset.edit)));document.querySelectorAll('[data-delete-entry]').forEach(b=>b.onclick=()=>{if(confirm('Eintrag löschen?')){db.entries=db.entries.filter(x=>x.id!==b.dataset.deleteEntry);put();render()}});document.querySelectorAll('[data-edit-strain]').forEach(b=>b.onclick=()=>strainForm(db.strains.find(x=>x.id===b.dataset.editStrain)));document.querySelectorAll('[data-del-strain]').forEach(b=>b.onclick=()=>{db.strains=db.strains.filter(x=>x.id!==b.dataset.delStrain);put();render()});document.querySelectorAll('[data-edit-device]').forEach(b=>b.onclick=()=>deviceForm(db.devices.find(x=>x.name===b.dataset.editDevice)));document.querySelectorAll('[data-del-device]').forEach(b=>b.onclick=()=>{if(db.entries.some(x=>x.device===b.dataset.delDevice))return toast('Gerät wird noch verwendet');db.devices=db.devices.filter(x=>x.name!==b.dataset.delDevice);put();render()});document.querySelectorAll('[data-del-photo]').forEach(b=>b.onclick=()=>{db.photos=db.photos.filter(x=>x.id!==b.dataset.delPhoto);put();render()});document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>courseView(courses.find(c=>c.id===b.dataset.course)));document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{let q=questData.find(q=>q.id===b.dataset.claim);if(!q||db.game.quests.includes(q.id)||!q.check())return;db.game.quests.push(q.id);db.game.xp=(db.game.xp||0)+q.xp;db.game.coins=(db.game.coins||0)+q.coins;put();render()})}
function newBoot(){db.entries=db.entries.map(e=>{let m=String(e.notes||'').match(/(?:anzahl\s*)?(?:züge|zuege|puffs?)\s*[:=]?\s*(\d+)/i);if(!e.puffs&&m)e.puffs=m[1];return e});put();render()}
newBoot();
handlePasswordRecovery();
